     *
     * @param configPath the path to the XML configuration file
     * @return an org.w3c.dom.Document object representing the parsed XML content
     * @throws Exception if the file cannot be read, the XML format is invalid,
     *                   or any other parsing error occurs
     */
    public Document loadConfig(String configPath) throws Exception {
