        if (configPath == null) {
            throw new IllegalArgumentException("Configuration path cannot be null");
        }

        if (configPath.trim().isEmpty()) {
            throw new IllegalArgumentException("Configuration path cannot be empty");
        }

        // Check if file exists
        File configFile = new File(configPath);
        if (!configFile.exists()) {
            throw new java.io.FileNotFoundException("Configuration file not found: " + configPath);
        }

        if (!configFile.isFile()) {
            throw new IllegalArgumentException("Path does not point to a file: " + configPath);
        }

